import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
import static org.junit.jupiter.api.Assertions.*;
class CorePatchGuardTest {
 @TempDir Path dir;
 ClassNode core(){ClassNode c=new ClassNode();c.version=Opcodes.V21;c.access=Opcodes.ACC_PUBLIC;c.name=MergeFactionFacade.OWNER;c.superName="java/lang/Object";c.fields.add(new FieldNode(Opcodes.ACC_PRIVATE,"selected","Ljava/util/Map;",null,null));c.methods.add(method("transactNetworkInventory",MergeFactionFacade.TX));c.methods.add(method("untouched","()V"));return c;}
 MethodNode method(String name,String desc){MethodNode m=new MethodNode(Opcodes.ACC_PUBLIC,name,desc,null,null);m.visitCode();m.visitInsn(Opcodes.RETURN);m.visitMaxs(0,8);m.visitEnd();return m;}
 Path write(ClassNode c,String name)throws Exception{ClassWriter w=new ClassWriter(0);c.accept(w);Path p=dir.resolve(name);Files.write(p,w.toByteArray());return p;}
 Path donor(){return Path.of(System.getProperty("donorClasses"),"com/example/dunerealms/DuneCore.class");}
 void rejected(ClassNode c)throws Exception{Path output=dir.resolve("rejected.class");assertThrows(IllegalStateException.class,()->MergeFactionFacade.main(new String[]{write(c,"before.class").toString(),donor().toString(),output.toString()}));assertFalse(Files.exists(output));}
 @Test void addsOnlyFacadeAndNamespacedLambdaAndPreservesEveryExistingMethod()throws Exception{ClassNode c=core();Map<String,byte[]> before=new HashMap<>();for(MethodNode m:c.methods)before.put(m.name+m.desc,MergeFactionFacade.methodBytes(m));Path output=dir.resolve("after.class");MergeFactionFacade.main(new String[]{write(c,"before.class").toString(),donor().toString(),output.toString()});ClassNode after=MergeFactionFacade.read(Files.readAllBytes(output));assertEquals(c.fields.size(),after.fields.size());assertEquals(c.methods.size()+2,after.methods.size());assertTrue(after.methods.stream().anyMatch(m->m.name.equals("adminAssignFaction")));assertEquals(1,after.methods.stream().filter(m->m.name.startsWith("alpha$staffFaction$")).count());for(MethodNode m:after.methods)if(before.containsKey(m.name+m.desc))assertArrayEquals(before.get(m.name+m.desc),MergeFactionFacade.methodBytes(m));}
 @Test void wrongOwnerCannotBePatched()throws Exception{ClassNode c=core();c.name="Other";rejected(c);}
 @Test void missingAuthoritativeMapCannotBePatched()throws Exception{ClassNode c=core();c.fields.clear();rejected(c);}
 @Test void missingOrStaticCheckpointCannotBeReplacedByDonorStub()throws Exception{ClassNode c=core();c.methods.remove(0);rejected(c);c=core();c.methods.get(0).access|=Opcodes.ACC_STATIC;rejected(c);}
 @Test void existingFacadeOrReservedLambdaCannotBeDuplicated()throws Exception{ClassNode c=core();c.methods.add(method("adminAssignFaction",MergeFactionFacade.API));rejected(c);c=core();c.methods.add(method("alpha$staffFaction$0","()V"));rejected(c);}
 ClassNode gui(){ClassNode c=new ClassNode();c.version=Opcodes.V21;c.access=Opcodes.ACC_PUBLIC;c.name="com/example/dunerealms/ConfigurableGui";c.superName="java/lang/Object";for(String name:List.of("open","execute")){MethodNode m=new MethodNode(Opcodes.ACC_PUBLIC,name,"()V",null,null);m.instructions.add(new InsnNode(Opcodes.ACONST_NULL));m.instructions.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"com/example/dunerealms/AdminGui","canUse","(Lorg/bukkit/entity/Player;)Z",false));m.instructions.add(new InsnNode(Opcodes.POP));if(name.equals("execute")){m.instructions.add(new LdcInsnNode("dune admin"));m.instructions.add(new InsnNode(Opcodes.POP));}m.instructions.add(new InsnNode(Opcodes.RETURN));m.maxStack=1;m.maxLocals=1;c.methods.add(m);}c.methods.add(method("untouched","()V"));return c;}
 @Test void staffRoutingChangesExactlyTwoGuardsAndOneNamespacedCommand()throws Exception{ClassNode c=gui();byte[] untouched=StaffRoutePatch.canonical(c.methods.get(2));Path output=dir.resolve("gui-after.class");StaffRoutePatch.main(new String[]{write(c,"gui.class").toString(),output.toString()});ClassNode after=MergeFactionFacade.read(Files.readAllBytes(output));assertArrayEquals(untouched,StaffRoutePatch.canonical(after.methods.get(2)));long guards=0,commands=0;for(MethodNode m:after.methods)for(AbstractInsnNode i:m.instructions){if(i instanceof MethodInsnNode call&&call.owner.endsWith("/StaffMenuBridge")&&call.name.equals("available"))guards++;if(i instanceof LdcInsnNode v&&"dunemenus:dunemenus staff".equals(v.cst))commands++;}assertEquals(2,guards);assertEquals(1,commands);}
 @Test void unexpectedGuiOwnerOrPatchShapeFailsWithoutOutput()throws Exception{for(boolean owner:List.of(true,false)){ClassNode c=gui();if(owner)c.name="Other";else c.methods.remove(0);Path output=dir.resolve("gui-rejected.class");assertThrows(IllegalStateException.class,()->StaffRoutePatch.main(new String[]{write(c,"gui-reject.class").toString(),output.toString()}));assertFalse(Files.exists(output));}}
}
